class Solution {
    private int[][] trie = new int[100001][26];
    private boolean[] end = new boolean[100001];
    private int idx = 0;

    public String replaceWords(List<String> dictionary, String sentence) {
        for (String root : dictionary) {
            int node = 0;
            for (char c : root.toCharArray()) {
                int ci = c - 'a';
                if (trie[node][ci] == 0) trie[node][ci] = ++idx;
                node = trie[node][ci];
            }
            end[node] = true;
        }
        StringBuilder sb = new StringBuilder();
        for (String word : sentence.split(" ")) {
            if (sb.length() > 0) sb.append(' ');
            int node = 0;
            boolean found = false;
            for (int i = 0; i < word.length(); i++) {
                int ci = word.charAt(i) - 'a';
                if (trie[node][ci] == 0) break;
                node = trie[node][ci];
                if (end[node]) {
                    sb.append(word, 0, i + 1);
                    found = true;
                    break;
                }
            }
            if (!found) sb.append(word);
        }
        return sb.toString();
    }
}
